sep = {'zh-Hans':'、','zh-Hant':'、','ja':'・'}
dc = {'en': dc_en_old.replace('Metal, Uranium', 'Metal, Gold, Uranium')}
for l in L:
    old = json.load(open(f'lang/{l}.json'))[dc_en_old]
    assert metal[l] in old, l
